            "english": "Pass the buck to someone else? Absolutely not; leadership requires taking ultimate personal responsibility for our team's failings.",
            "chinese": "遇到危机甩锅踢皮球给别人（Pass the buck）？门儿都没有！作为将帅领袖，核心要义就是在全军受挫时敢于把责任全额揽在自己肩膀上！",
