            "chinese": "在应对高管尖锐提问时，永远要在第一时间以真诚优雅的姿态充分肯定对方问题的深刻价值，随后再借力打力、四两拨千斤丝滑切入你早已烂熟于心的核心主张！",
            "phonetic": null,
            "note": null
