            "english": "Let us lead the industry from the front, setting the global benchmark that competitors will spend years trying to catch.",
            "chinese": "让我们当仁不让担当起引领整个行业大潮的开路先锋吧！亲手树立起一座让所有后来追赶者在未来数年内唯有望尘莫及的全球至尊标杆！",
