            "english": "Summarize the overarching existential choice: the pain of remaining static versus the exhilarating triumph of forward evolution.",
            "chinese": "在最后一秒再次精辟升华全场最核心的灵魂拷问：是忍受原地踏步注定沦为炮灰的无尽煎熬，还是张开双臂迎接破茧成蝶进化凯旋的无上荣光！",
