            "id": "rec-study-abroad-ch7-s14",
            "english": "Formatting margins and page numbers properly reflects professional craftsmanship in academic submission.",
            "chinese": "规范设置页边距和页码等排版格式，体现了提交正式学术文稿时严谨专业的治学素养。",
            "phonetic": null,
            "note": null
